<div class="mt-4 overflow-hidden rounded-xl border border-line bg-white"><div class="overflow-x-auto"><table class="w-full min-w-[650px] text-left text-sm"><thead class="border-b border-line bg-[#FBFBF8] text-xs uppercase tracking-wide text-neutral-500"><tr><th class="p-4">Pesanan</th><?php if(current_user()['role']==='admin'): ?><th class="p-4">Pelanggan</th><?php endif ?><th class="p-4">Layanan</th><th class="p-4">Status</th><th class="p-4">Dibuat</th><th class="p-4"></th></tr></thead><tbody><?php if(!$orders): ?><tr><td colspan="6" class="p-8 text-center text-neutral-500">Belum ada pesanan. Proyek pertamamu bisa dimulai di sini.</td></tr><?php endif ?><?php foreach($orders as $order): ?><tr class="border-b border-line last:border-0"><td class="p-4 font-medium"><?= e($order['title']) ?><span class="mt-1 block text-xs text-neutral-400">#<?= (int)$order['id'] ?></span></td><?php if(current_user()['role']==='admin'): ?><td class="p-4"><?= e($order['customer_name']) ?></td><?php endif ?><td class="p-4"><?= e($order['service_name']) ?></td><td class="p-4"><span class="rounded-full bg-[#F5F3EA] px-3 py-1 text-xs"><?= e(status_label($order['status'])) ?></span></td><td class="p-4 text-neutral-500"><?= e(date('d M Y',strtotime($order['created_at']))) ?></td><td class="p-4"><a class="underline decoration-sun underline-offset-4" href="<?= current_user()['role']==='admin'?'/admin/orders/':'/orders/' ?><?= (int)$order['id'] ?>">Buka ↗</a></td></tr><?php endforeach ?></tbody></table></div></div>
